class Document {                                   // handle (value semantics)
public:
    void rename(std::string title) {
        if (body_.use_count() > 1)                 // the body is shared
            body_ = std::make_shared<Body>(*body_);  // detach before mutating
        body_->title = std::move(title);
    }
private:
    std::shared_ptr<Body> body_;                   // shared representation (counted body)
};
